(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.022-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.016+t*0.3)*12;
  const w2x = Math.sin((x+y)*0.012-t*0.15)*8 + Math.cos((x-y)*0.01+t*0.2)*6;
  const w2y = Math.cos((x-y)*0.014+t*0.17)*8 + Math.sin((x+y)*0.009-t*0.22)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*55, 0.075, 2.2, 1.0],
    [320+Math.cos(t*0.45)*110, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.5+1)*50, 0.1, 2.3, 0.8],
    [420+Math.cos(t*0.4+2)*60, 200+Math.sin(t*0.65+4)*55, 0.07, 2.6, 1.15]
  ];
  let aS=0, iS=0, cF=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const fade = Math.exp(-d*0.003);
    aS += (Math.sin(d*f-t*sp)+Math.sin(d*f*1.5-t*sp*0.7+0.8))*0.5*w*fade;
    iS += (Math.sin(d*f*0.6+t*sp*0.5+1.5)+Math.cos(d*f*0.9-t*sp*0.3))*0.5*w*fade;
    cF += Math.sin(d*f*2.2-t*sp*1.3)*fade*w*0.15;
  }
  const act=aS/8, inh=iS/8, cplx=cF/8;
  const bg1 = (Math.sin(sx*0.035+sy*0.028+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.1+t*2.2)*0.18+Math.sin((sx-sy)*0.085-t*1.8)*0.18;
  const bg3 = Math.sin(sx*0.06+t*1.4)*Math.cos(sy*0.055-t*1.1)*0.15;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp2 = Math.sin(dist*0.06-ang*2-t*1.8)*Math.cos(dist*0.025+ang*5-t*0.7);
  const spiral = (sp1*0.35+sp2*0.2);
  const lap = (Math.sin(sx*0.16)*Math.sin(sy*0.16)+Math.sin((sx+sy)*0.11+t)*0.4+Math.sin((sx-sy)*0.09-t*0.8)*0.3)*0.8;
  const react = Math.tanh((act-inh*0.65+bg*0.25+spiral+cplx*0.4+lap*0.15)*2.0);
  const sharp = react>0.3?Math.tanh((react-0.3)*5)+0.3:Math.tanh(react*4);
  const glow = Math.exp(-Math.abs(react)*3)*0.4;
  const v = (sharp*0.7+glow*0.3)*0.5+0.5;
  const lum = 0.82+Math.sin(react*Math.PI*1.2)*0.18;
  const edge = Math.abs(sharp)>0.65?1.18:Math.abs(sharp)>0.3?1.08:1.0;
  const pal = [
    [6,12,52],[10,42,88],[14,78,118],[18,118,132],
    [50,158,130],[140,185,90],[210,195,55],
    [225,150,60],[215,100,65],[185,60,72],
    [130,35,72],[75,18,58],[30,10,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sm = f*f*(3-2*f);
  const m = lum*edge;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*m)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*m)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*m)|0
  ];
}
